/// every feature hook slot of this crate and the crates below, with whether it is filled
pub fn feature_hook_slots() -> Vec<(&'static str, bool)> {
    let mut slots: Vec<(&'static str, bool)> = Vec::new();
    slots.extend(riseonly_pages_chat::feature_hook_slots());
    slots.extend(riseonly_pages_chat_info::feature_hook_slots());
    slots.extend(riseonly_pages_media::feature_hook_slots());
    slots.extend(riseonly_pages_misc_a::feature_hook_slots());
    slots.extend(riseonly_pages_misc_b::feature_hook_slots());
    slots.extend(riseonly_pages_misc_c::feature_hook_slots());
    slots.extend(riseonly_pages_music::feature_hook_slots());
    slots.extend(riseonly_pages_post::feature_hook_slots());
    slots.extend(riseonly_pages_user::feature_hook_slots());
    slots
}

#[cfg(test)]
mod feature_hook_slots_tests {
    #[test]
    fn install_feature_hooks_fills_every_slot() {
        crate::install_feature_hooks();
        let mut empty: Vec<&str> =
            crate::feature_hook_slots().into_iter().filter(|(_, filled)| !filled).map(|(name, _)| name).collect();
        empty.sort_unstable();
        empty.dedup();
        assert!(empty.is_empty(), "slots install_feature_hooks() leaves empty: {empty:?}");
    }
}
